+  if (isHighRiskAssertion(assertion)) {
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: ['high_risk_assertions_must_not_auto_accept'],
+    };
+  }
+  if (assertion.status_proposal === 'accepted') {
+    const eligibility = acceptedEligibility(assertion, thresholds, inputs);
+    if (eligibility.eligible) {
+      return {
+        layer: 'accepted',
+        decision: 'accepted',
+        reason_codes: [],
+      };
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: eligibility.reasons,
+      failed_evidence_conditions: eligibility.failed_evidence_conditions,
+    };
+  }
+  if (assertion.status_proposal === 'provisional_safe') {
+    const eligibility = provisionalEligibility(assertion, thresholds, inputs);
+    if (eligibility.eligible) {
+      return {
+        layer: 'provisional_safe',
+        decision: 'provisional_safe',
+        reason_codes: [],
+      };
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: eligibility.reasons,
+    };
+  }
+  return {
+    layer: 'review_required',
+    decision: 'review_required',
+    reason_codes: ['status_proposal_not_promotion_eligible'],
+  };
+}
+
+function sortEntries(items) {
+  return (Array.isArray(items) ? items.filter(isObject) : []).sort((left, right) => (
+    compareByteOrder(left.source_assertion_id, right.source_assertion_id) ||
+    compareByteOrder(left.promotion_assertion_id, right.promotion_assertion_id)
