+}
+
+function buildLayers({ assertions, rowIndex, context }) {
+  const accepted = [];
+  const provisionalSafe = [];
+  const reviewRequired = [];
+  const rejected = [];
+  const blockedQuarantined = [];
+  const failedAcceptedEvidenceConditions = [];
