+  for (const assertion of assertions) {
+    const row = rowForAssertion(assertion, rowIndex);
+    const routed = routeAssertion(assertion, context);
+    const entry = buildLayerEntry({
+      assertion,
+      layer: routed.layer,
+      decision: routed.decision,
+      reasonCodes: routed.reason_codes,
+      row,
+      paths: context.paths,
+      inputs: context.inputs,
+      generatedAt: context.generatedAt,
+    });
