+    if (routed.layer === 'accepted') accepted.push(entry);
+    else if (routed.layer === 'provisional_safe') provisionalSafe.push(entry);
+    else if (routed.layer === 'rejected') rejected.push(entry);
+    else if (routed.layer === 'blocked_quarantined') blockedQuarantined.push(entry);
+    else reviewRequired.push(entry);
