+  return {
+    accepted: sortEntries(accepted),
+    provisionalSafe: sortEntries(provisionalSafe),
+    reviewRequired: sortEntries(reviewRequired),
+    rejected: sortEntries(rejected),
+    blockedQuarantined: sortEntries(blockedQuarantined),
+    failedAcceptedEvidenceConditions,
+  };
+}
+
+function layerSummary(items) {
+  return {
+    assertion_count: items.length,
+    by_predicate: countBy(items, 'predicate'),
+    by_question: countBy(items, 'question_row_id'),
+    by_topic_component_group: countBy(items, 'topic_component_group'),
