+    source_candidate_assertion_count: assertions.length,
+    source_raw_candidate_assertion_ids: rawIds,
+    promoted_source_assertion_ids: promotedIds,
+    promoted_raw_candidate_intersection_ids: intersection,
+    intersection_count: intersection.length,
+    accepted_and_provisional_are_delta_layers_not_raw_candidate_layer: true,
