+  return {
+    active: true,
+    blocker_status: 'accepted_promotion_blocked',
+    reason:
+      'accepted_count is zero after applying the #1366 calibrated promotion thresholds to the #1365 calibration shard.',
+    failed_threshold_refs: [
+      'min_accepted_edges_for_calibration_success',
+      'min_accepted_questions_for_calibration_success',
+      'accepted_count_required_for_rag_manifest',
