+    threshold_values: {
+      min_accepted_edges_for_calibration_success:
+        thresholdValue(thresholds, 'min_accepted_edges_for_calibration_success', null),
+      min_accepted_questions_for_calibration_success:
+        thresholdValue(thresholds, 'min_accepted_questions_for_calibration_success', null),
+      accepted_count_required_for_rag_manifest:
