+
+function buildSummary({ assertions, layers, rowIndex }) {
+  const promoted = [...layers.accepted, ...layers.provisionalSafe];
+  const allEntries = [
+    ...layers.accepted,
+    ...layers.provisionalSafe,
+    ...layers.reviewRequired,
+    ...layers.rejected,
+    ...layers.blockedQuarantined,
