+  const criticalDiagnostics = diagnostics.filter((diagnostic) => diagnostic.severity === 'critical');
+  const promoted = [...layers.accepted, ...layers.provisionalSafe];
+  const allEntries = [
+    ...layers.accepted,
+    ...layers.provisionalSafe,
+    ...layers.reviewRequired,
+    ...layers.rejected,
+    ...layers.blockedQuarantined,
+  ];
+  const thresholdValues = promotionRun.threshold_context.threshold_values;
+  const acceptedQuestions = promotionRun.summary.accepted_question_count;
+  const acceptedThresholdMet =
+    promotionRun.summary.accepted_count >= thresholdValues.min_accepted_edges_for_calibration_success &&
+    acceptedQuestions >= thresholdValues.min_accepted_questions_for_calibration_success &&
+    promotionRun.summary.accepted_count >= thresholdValues.accepted_count_required_for_rag_manifest;
+  const highRiskAccepted = layers.accepted.filter((item) => isHighRiskAssertion({
+    predicate: item.predicate,
+    risk_tier: item.risk_tier,
+  }));
+  const reviewRequiredPerQuestion = promotionRun.summary.review_required_per_question ?? 0;
+  const reviewRequiredRatio = promotionRun.summary.review_required_ratio ?? 0;
+
+  const checks = [
+    acceptedThresholdMet
+      ? passCheck('accepted_count_positive_and_threshold_backed', {
+        accepted_count: promotionRun.summary.accepted_count,
+        accepted_question_count: acceptedQuestions,
+      })
+      : promotionRun.validator_backed_blocker?.active === true
+        ? blockedCheck('accepted_count_positive_and_threshold_backed', 'validator_backed_zero_accepted_blocker_active', {
+          blocker: promotionRun.validator_backed_blocker,
+        })
+        : failCheck('accepted_count_positive_and_threshold_backed', 'accepted_thresholds_not_met', {
+          accepted_count: promotionRun.summary.accepted_count,
+          accepted_question_count: acceptedQuestions,
+        }),
+    ragLiteHvyManifest.summary.accepted_count === promotionRun.summary.accepted_count &&
+      ragLiteHvyManifest.summary.provisional_safe_count === promotionRun.summary.provisional_safe_count &&
+      ragLiteHvyManifest.layers.accepted.assertion_count !==
+        ragLiteHvyManifest.layers.provisional_safe.assertion_count
+      ? passCheck('accepted_provisional_counts_reported_separately_in_rag_manifest', {
+        accepted_count: ragLiteHvyManifest.summary.accepted_count,
+        provisional_safe_count: ragLiteHvyManifest.summary.provisional_safe_count,
+      })
+      : failCheck('accepted_provisional_counts_reported_separately_in_rag_manifest', 'rag_manifest_counts_not_separated'),
+    criticalDiagnostics.length === 0 &&
+      inputs.thresholds?.issue === 1366 &&
+      validatorStatus(inputs.thresholdsValidator) === 'pass' &&
+      validatorStatus(inputs.calibrationValidator) === 'pass'
+      ? passCheck('calibrated_thresholds_loaded_and_validated', {
+        thresholds_issue: inputs.thresholds?.issue,
+        thresholds_validator_status: validatorStatus(inputs.thresholdsValidator),
+        calibration_validator_status: validatorStatus(inputs.calibrationValidator),
+      })
+      : failCheck('calibrated_thresholds_loaded_and_validated', 'threshold_or_calibration_validator_not_pass', {
+        critical_diagnostics: criticalDiagnostics,
+        thresholds_issue: inputs.thresholds?.issue ?? null,
+        thresholds_validator_status: validatorStatus(inputs.thresholdsValidator),
+        calibration_validator_status: validatorStatus(inputs.calibrationValidator),
+      }),
+    ['by_predicate', 'by_question', 'by_topic_component_group', 'by_risk_tier', 'by_evidence_family']
+      .every((field) => isObject(promotionRun.counts.accepted[field]) &&
+        isObject(promotionRun.counts.provisional_safe[field]))
+      ? passCheck('count_breakdowns_cover_required_dimensions', {
+        accepted_dimensions: Object.keys(promotionRun.counts.accepted),
+        provisional_safe_dimensions: Object.keys(promotionRun.counts.provisional_safe),
+      })
+      : failCheck('count_breakdowns_cover_required_dimensions', 'required_count_dimension_missing'),
+    highRiskAccepted.length === 0
+      ? passCheck('high_risk_assertions_not_auto_accepted', { high_risk_accepted_count: 0 })
+      : failCheck('high_risk_assertions_not_auto_accepted', 'high_risk_assertion_accepted', {
