+
+function isRawCandidateLike(assertion) {
+  return hasAnyState(assertion, RAW_STATES);
+}
+
+function isRejectedLike(assertion) {
+  return hasAnyState(assertion, REJECTED_STATES);
+}
+
+function isBlockedLike(assertion) {
+  return hasAnyState(assertion, BLOCKED_STATES);
+}
