+
+function normalizeAssertions(shardOutput, diagnostics) {
+  if (!Array.isArray(shardOutput?.semantic_assertion_proposals)) {
+    diagnostics.push({
+      code: 'semantic_assertion_proposals_missing',
+      role: 'semantic_kg_codex_shard_output',
+      severity: 'critical',
+    });
+    return [];
+  }
+
+  return shardOutput.semantic_assertion_proposals
+    .map((assertion, index) => {
+      if (!isObject(assertion) || typeof assertion.assertion_id !== 'string') {
+        diagnostics.push({
+          code: 'semantic_assertion_proposal_malformed',
+          role: 'semantic_kg_codex_shard_output',
+          severity: 'critical',
+          json_pointer: `/semantic_assertion_proposals/${index}`,
+        });
+        return {
+          source_index: index,
+          malformed: true,
+          assertion_id: `malformed_assertion_${index}`,
+        };
+      }
+      return {
+        ...assertion,
+        source_index: index,
+        source_json_pointer: `/semantic_assertion_proposals/${index}`,
