+function upstreamValidatorsPass(inputs) {
+  return validatorStatus(inputs.thresholdsValidator) === 'pass' &&
+    validatorStatus(inputs.calibrationValidator) === 'pass';
+}
+
+function validatorPassCount(inputs) {
