+  if (acceptedPolicy?.enabled !== true) {
+    reasons.push('accepted_policy_disabled_for_predicate_risk_tier');
+  }
+  if (!upstreamValidatorsPass(inputs)) {
+    reasons.push('upstream_validators_must_pass_before_promotion');
+  }
+  if (validatorPassCount(inputs) < (acceptedPolicy?.min_validator_pass_count ?? 2)) {
+    reasons.push('accepted_min_validator_pass_count_not_met');
+  }
+  if (!hasEvidence(assertion)) {
+    reasons.push('evidence_refs_required_for_promotion');
+    failedEvidenceConditions.push({
+      condition: 'evidence_refs_required_for_promotion',
+      assertion_id: assertion?.assertion_id ?? null,
+    });
+  }
+  if (families.length < minEvidenceFamilyCount) {
+    reasons.push('min_evidence_family_count_for_accepted_not_met');
+    failedEvidenceConditions.push({
+      condition: 'min_evidence_family_count_for_accepted',
+      assertion_id: assertion?.assertion_id ?? null,
+      required: minEvidenceFamilyCount,
+      actual: families.length,
