+    reasons.push('accepted_requires_official_or_checked_in_source');
+    failedEvidenceConditions.push({
+      condition: 'accepted_requires_official_or_checked_in_source',
+      assertion_id: assertion?.assertion_id ?? null,
+      evidence_families: families,
