+    reasons.push('provisional_policy_disabled_for_predicate_risk_tier');
+  }
+  if (!upstreamValidatorsPass(inputs)) {
+    reasons.push('upstream_validators_must_pass_before_promotion');
+  }
+  if (validatorPassCount(inputs) < (provisionalPolicy?.min_validator_pass_count ?? 1)) {
+    reasons.push('provisional_min_validator_pass_count_not_met');
+  }
+  if (!hasEvidence(assertion)) {
+    reasons.push('evidence_refs_required_for_promotion');
+  }
+  if (families.length < minEvidenceFamilyCount) {
+    reasons.push('min_evidence_family_count_for_provisional_not_met');
+  }
