+      path: paths.thresholdsValidatorIn,
+      status: validatorStatus(inputs.thresholdsValidator),
+    },
+    {
+      role: 'semantic_kg_codex_calibration_shard_validator',
+      path: paths.calibrationValidatorIn,
+      status: validatorStatus(inputs.calibrationValidator),
+    },
+  ];
