+  return {
+    promotion_assertion_id:
+      `semkg-calibrated-promotion:${ISSUE}:${assertion?.assertion_id ?? assertion?.source_index}`,
+    source_assertion_id: assertion?.assertion_id ?? null,
+    source_shard_id: inputs.shardOutput?.shard_id ?? null,
+    source_status_before_promotion: assertion?.status_proposal ?? assertion?.source_status ?? null,
+    subject_ref: assertion?.subject ?? null,
+    predicate: assertion?.predicate ?? null,
+    object_ref: assertion?.object ?? null,
+    scope_ref: assertion?.scope ?? null,
+    question_row_id: questionId,
+    topic_component_group: row?.topic_component_group ?? 'none',
+    source_row_ids: Array.isArray(assertion?.source_row_ids) ? assertion.source_row_ids : [],
