+      validator_refs: validatorRefs(inputs, paths),
+    },
+    content_hash: {
+      algorithm: 'sha256',
+      value: sha256Value({
+        assertion_id: assertion?.assertion_id ?? null,
+        predicate: assertion?.predicate ?? null,
+        subject: assertion?.subject ?? null,
+        object: assertion?.object ?? null,
+        scope: assertion?.scope ?? null,
+        layer,
+        evidence_refs: assertion?.evidence_refs ?? [],
