+
+function routeAssertion(assertion, context) {
+  const { thresholds, inputs } = context;
+  if (!isObject(assertion) || assertion.malformed) {
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: ['semantic_assertion_proposal_malformed'],
+    };
+  }
+  if (isRawCandidateLike(assertion)) {
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: ['raw_candidate_excluded_from_promoted_layers'],
+    };
+  }
