+        layer: 'accepted',
+        decision: 'accepted',
+        reason_codes: [],
+      };
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: eligibility.reasons,
+      failed_evidence_conditions: eligibility.failed_evidence_conditions,
+    };
+  }
+  if (assertion.status_proposal === 'provisional_safe') {
+    const eligibility = provisionalEligibility(assertion, thresholds, inputs);
+    if (eligibility.eligible) {
+      return {
+        layer: 'provisional_safe',
+        decision: 'provisional_safe',
+        reason_codes: [],
+      };
+    }
+    return {
+      layer: 'review_required',
+      decision: 'review_required',
+      reason_codes: eligibility.reasons,
+    };
+  }
