+function sortEntries(items) {
+  return (Array.isArray(items) ? items.filter(isObject) : []).sort((left, right) => (
+    compareByteOrder(left.source_assertion_id, right.source_assertion_id) ||
+    compareByteOrder(left.promotion_assertion_id, right.promotion_assertion_id)
