+    assertion_count: items.length,
+    by_predicate: countBy(items, 'predicate'),
+    by_question: countBy(items, 'question_row_id'),
+    by_topic_component_group: countBy(items, 'topic_component_group'),
+    by_risk_tier: countBy(items, 'risk_tier'),
+    by_evidence_family: countEvidenceFamilies(items),
